"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface SquareDashedIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface SquareDashedIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const SquareDashedIcon = forwardRef<
 SquareDashedIconHandle,
 SquareDashedIconProps
>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const cornerVariants: Variants = {
   normal: { x: 0, y: 0 },
   animate: ([dx, dy]: number[]) => ({
    x: [0, 1.5 * dx, 0],
    y: [0, 1.5 * dy, 0],
    transition: { duration: 0.6 * duration, ease: "easeInOut" },
   }),
  };

  const dashVariants: Variants = {
   normal: { opacity: 1 },
   animate: (i: number) => ({
    opacity: [1, 0.2, 1],
    transition: {
     duration: 0.4 * duration,
     ease: "easeInOut",
     delay: i * 0.05 * duration,
    },
   }),
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path
       d="M5 3a2 2 0 0 0-2 2"
       variants={cornerVariants}
       custom={[-1, -1]}
      />
      <m.path
       d="M19 3a2 2 0 0 1 2 2"
       variants={cornerVariants}
       custom={[1, -1]}
      />
      <m.path
       d="M21 19a2 2 0 0 1-2 2"
       variants={cornerVariants}
       custom={[1, 1]}
      />
      <m.path
       d="M5 21a2 2 0 0 1-2-2"
       variants={cornerVariants}
       custom={[-1, 1]}
      />
      <m.path d="M9 3h1" variants={dashVariants} custom={0} />
      <m.path d="M9 21h1" variants={dashVariants} custom={5} />
      <m.path d="M14 3h1" variants={dashVariants} custom={1} />
      <m.path d="M14 21h1" variants={dashVariants} custom={4} />
      <m.path d="M3 9v1" variants={dashVariants} custom={7} />
      <m.path d="M21 9v1" variants={dashVariants} custom={2} />
      <m.path d="M3 14v1" variants={dashVariants} custom={6} />
      <m.path d="M21 14v1" variants={dashVariants} custom={3} />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

SquareDashedIcon.displayName = "SquareDashedIcon";
export { SquareDashedIcon };
